"""Build the editable HTML slide deck from reviewed analysis outputs."""
from pathlib import Path
import json
from html import escape

root=Path(__file__).resolve().parents[1]
a=json.loads((root/'analysis/dataset_audit.json').read_text())
m=json.loads((root/'analysis/market_analysis.json').read_text())
f=json.loads((root/'analysis/scenarios.json').read_text())
slides=[]
def card(title,body,cls=''):
    return f'<article class="card {cls}"><h3>{title}</h3>{body}</article>'
def grid(*cards,cols=3):
    return f'<div class="grid c{cols}">'+''.join(cards)+'</div>'
def metric(number,label):
    return f'<div class="metric"><strong>{number}</strong><span>{label}</span></div>'
def table(headers,rows):
    return '<table><thead><tr>'+''.join(f'<th>{h}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>'
def note(t):return f'<div class="note">{t}</div>'
from design import make_pages, team, bars, panel, process, architecture, item, column, trio

sections=[('Резюме',2),('Аудитория',3),('Рынок',4),('Продукт',5),('Финансы',7),('Запуск',8),('Приложения',9),('Команда',29)]
def slide(section,title,body,source='Синтетический датасет VK Case Champ, сентябрь 2026.',cls=''):
    i=len(slides)+1
    active=max((page for label,page in sections if page<=i),default=0)
    nav=''.join(f'<a class="{("on" if n==active else "")}" href="#s{n}">{label}</a>' for label,n in sections)
    slides.append(f'<section class="slide {cls}" id="s{i}"><header><img src="assets/logos.png" alt="VK Education и ВКонтакте"><nav>{nav}</nav></header><h1>{title}</h1><main>{body}</main><footer><span>{source}</span><b>{i:02d}</b></footer></section>')

sources=['','Сентябрь 2026. Лист «Бизнесы».','Доля бизнесов с заказом среди сообществ с активными товарами.','Лист «Источники». Полное сравнение каналов на с. 17.','Экраны кабинета и мобильной карточки в прототипе «Пульт продаж».','Сценарий покупки в сообществе.','Базовые предпосылки на с. 18, расчёт на с. 19.','Мощность 80%, двусторонний уровень значимости 5%. Подбор размера групп на с. 20 и 26.']
for k,(title,body) in enumerate(make_pages(f)):
    slide('',title,body,sources[k],'cover' if k==0 else '')

