def volume_chart(key):
    peak=max(row[key] for row in categories)
    return ''.join(f'<div class="volume"><span>{row["category"]}</span><i><u style="width:{row[key]/peak:.2%}"></u></i><b>{row[key]:,}</b></div>'.replace(',',' ') for row in categories)
